import java.sql.*; import javax.naming.InitialContext; import org.apache.catalina.util.ServerInfo; public class App {  private String serverName = "localhost"; private String dbName = "library_db"; private String username = "root"; private String password = ""; private Connection connection = null; private Statement statement = null; private ResultSet resultset = null; private PreparedStatement preparedstatement = null; private InitialContext initialcontext = new InitialContext(); private DataSource datasource = (DataSource)initialcontext.lookup("java:comp/env/jdbc/library_db"); 
public Connection getConnection() {  try { this.connection = this.datasource.getConnection(); } catch(Exception exception) { System.out.println("Error getting database connection."); exception.printStackTrace(); } return this.connection; }
public String getServerName() { return this.serverName; } public String getDbName() { return this.dbName; } public String getUsername() { return this.username; } public String getPassword() { return this.password; } 
}